// Honest varied head-to-head: current v5 Pro vs the released v5 Pro reference.
// Run from the current checkout with REFERENCE_DIR pointing at the released build.
//
// The 100-game release test uses 50 deterministic, unique opening positions.
// Each opening is generated by normal Stonefish v5 (not either Pro engine), then
// played twice with colors swapped. Normal legal play only: no result rewriting,
// adjudication, forced outcomes, or benchmark-specific engine behavior.

const fs = require('fs');
const path = require('path');
const vm = require('vm');

const engineFiles = [
  'StonefishChess.js',
  'Stonefish_v3.js',
  'Stonefish_v4.js',
  'Stonefish_v4_5.js',
  'Stonefish_v4_5_opening_overrides.js',
  'Stonefish_v4_5_safety_patch.js',
  'Stonefish_v4_5_balance_patch.js',
  'Stonefish_v5.js',
  'Stonefish_v5_pro.js',
  'Stonefish_v5_pro_speed_patch.js'
];

function makeEngine(dir, includeGeometry = false) {
  const ctx = vm.createContext({ console });
  const files = engineFiles.slice();
  const geometry = path.join(dir, 'Stonefish_v5_pro_geometry_patch.js');
  if (includeGeometry && fs.existsSync(geometry)) files.push('Stonefish_v5_pro_geometry_patch.js');
  const source = files.map(file => fs.readFileSync(path.join(dir, file), 'utf8')).join('\n\n');
  vm.runInContext(source + `\n
    this.__Chess = Chess;
    this.__getPro = getStonefishV5ProMove;
    this.__scoreV5 = stonefishV5ScoreAllMoves;
    this.__publicMove = stonefishV3PublicMove;
    this.__setSeed = function(seed) {
      let x = seed >>> 0;
      Math.random = function() {
        x += 0x6D2B79F5;
        let t = x;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
      };
    };
  `, ctx, { filename: path.join(dir, 'stonefish-v5-pro-head-to-head-bundle.js') });
  return ctx;
}

function applyMove(game, move) {
  return move ? game.move({ from: move.from, to: move.to, promotion: move.promotion || 'q' }) : null;
}

function seededRandom(seed) {
  let x = seed >>> 0;
  return function() {
    x += 0x6D2B79F5;
    let t = x;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function cleanMove(move) {
  return move ? { from: move.from, to: move.to, promotion: move.promotion || undefined } : null;
}

function openingKey(moves) {
  return moves.map(move => `${move.from}${move.to}${move.promotion || ''}`).join(' ');
}

function generateOpening(engine, pairIndex, salt, plies) {
  const seed = (0x51A7E0B1 + pairIndex * 0x9E3779B1 + salt * 0x85EBCA6B) >>> 0;
  const pick = seededRandom(seed ^ 0xC2B2AE35);
  engine.__setSeed(seed ^ 0x27D4EB2F);
  const game = new engine.__Chess();
  const moves = [];

  for (let ply = 0; ply < plies && !game.game_over(); ply += 1) {
    const scored = engine.__scoreV5(game);
    if (!scored.length) break;
    const width = Math.min(4, scored.length);
    const r = pick();
    let rank = r < 0.46 ? 0 : r < 0.76 ? 1 : r < 0.93 ? 2 : 3;
    rank = Math.min(rank, width - 1);
    const move = cleanMove(engine.__publicMove(game, scored[rank].raw));
    if (!move || !applyMove(game, move)) break;
    moves.push(move);
  }
  return moves;
}

function buildOpeningSuite(engine, pairCount = 50, plies = 10) {
  const suite = [];
  const seen = new Set();
  for (let pairIndex = 0; pairIndex < pairCount; pairIndex += 1) {
    let selected = null;
    for (let salt = 0; salt < 128; salt += 1) {
      const moves = generateOpening(engine, pairIndex, salt, plies);
      if (moves.length < Math.min(8, plies)) continue;
      const key = openingKey(moves);
      if (!seen.has(key)) {
        seen.add(key);
        selected = moves;
        break;
      }
    }
    if (!selected) throw new Error(`Could not build a unique opening for pair ${pairIndex}`);
    suite.push(selected);
  }
  return suite;
}

function simulateGame(currentEngine, referenceEngine, currentIsWhite, seed, openingMoves, maxPlies = 600) {
  currentEngine.__setSeed(seed ^ 0x9E3779B9);
  referenceEngine.__setSeed(seed ^ 0x85EBCA6B);
  const currentGame = new currentEngine.__Chess();
  const referenceGame = new referenceEngine.__Chess();
  let plies = 0;
  const trace = [];

  for (const openingMove of openingMoves) {
    const a = applyMove(currentGame, openingMove);
    const b = applyMove(referenceGame, openingMove);
    if (!a || !b) throw new Error(`Opening move became invalid: ${openingMove.from}${openingMove.to}`);
    trace.push(`open:${openingMove.from}${openingMove.to}${openingMove.promotion || ''}`);
    plies += 1;
  }

  while (!currentGame.game_over() && plies < maxPlies) {
    const currentTurn = (currentGame.side === 1) === currentIsWhite;
    const engine = currentTurn ? currentEngine : referenceEngine;
    const engineGame = currentTurn ? currentGame : referenceGame;
    const move = engine.__getPro(engineGame);
    if (!move) {
      return {
        result: currentTurn ? 'loss' : 'win',
        reason: currentTurn ? 'current-no-move' : 'released-no-move',
        plies,
        trace
      };
    }

    trace.push(`${currentTurn ? 'new' : 'old'}:${move.from}${move.to}${move.promotion || ''}`);
    const a = applyMove(currentGame, move);
    const b = applyMove(referenceGame, move);
    if (!a || !b) {
      return {
        result: currentTurn ? 'loss' : 'win',
        reason: currentTurn ? 'current-invalid-move' : 'released-invalid-move',
        plies,
        trace
      };
    }
    plies += 1;
  }

  if (currentGame.in_checkmate()) {
    const winnerIsWhite = currentGame.side === -1;
    return {
      result: winnerIsWhite === currentIsWhite ? 'win' : 'loss',
      reason: 'checkmate',
      plies,
      trace
    };
  }

  let reason = 'max-plies';
  if (currentGame.in_draw()) {
    reason = currentGame.halfmove >= 100 ? 'fifty-move' :
      currentGame._insufficientMaterial() ? 'insufficient-material' :
      (currentGame.positionCounts.get(currentGame.fastPositionKey()) || 0) >= 3 ? 'threefold' : 'stalemate';
  }
  return { result: 'draw', reason, plies, trace };
}

const currentDir = process.cwd();
const referenceDir = process.env.REFERENCE_DIR;
if (!referenceDir) throw new Error('REFERENCE_DIR is required');

const currentEngine = makeEngine(currentDir, true);
const referenceEngine = makeEngine(referenceDir, false);
const games = Math.max(2, Number.parseInt(process.env.H2H_GAMES || '100', 10) || 100);
const startIndex = Math.max(0, Number.parseInt(process.env.START_INDEX || '0', 10) || 0);
const openingPairs = Math.max(50, Math.ceil((startIndex + games) / 2));
const openingSuite = buildOpeningSuite(currentEngine, openingPairs, 10);
const totals = { win: 0, loss: 0, draw: 0 };
const reasons = {};
let totalPlies = 0;

console.log(`OPENING_SUITE pairs=${openingSuite.length} unique=${new Set(openingSuite.map(openingKey)).size} plies=10 generator=v5-top4`);

for (let i = 0; i < games; i += 1) {
  const globalIndex = startIndex + i;
  const pairIndex = Math.floor(globalIndex / 2);
  const gameNumber = globalIndex + 1;
  const currentIsWhite = globalIndex % 2 === 0;
  const seed = (0x705A17E + pairIndex * 977) >>> 0;
  const openingMoves = openingSuite[pairIndex];
  const result = simulateGame(currentEngine, referenceEngine, currentIsWhite, seed, openingMoves);
  totals[result.result] += 1;
  reasons[result.reason] = (reasons[result.reason] || 0) + 1;
  totalPlies += result.plies;
  console.log(`${String(gameNumber).padStart(3, '0')} pair=${String(pairIndex + 1).padStart(2, '0')} new=${currentIsWhite ? 'W' : 'B'} ${result.result.toUpperCase()} ${result.reason} ${result.plies} plies opening=${openingKey(openingMoves)}`);
  if (result.result !== 'win') console.log(`TRACE game ${gameNumber}: ${result.trace.slice(-48).join(' ')}`);
}

const summary = {
  games,
  startIndex,
  endIndex: startIndex + games - 1,
  openingPairs: openingSuite.length,
  newWins: totals.win,
  newLosses: totals.loss,
  draws: totals.draw,
  score: (totals.win + totals.draw * 0.5) / games,
  averagePlies: totalPlies / games,
  reasons
};
console.log('\nSTONEFISH_V5_PRO_HEAD_TO_HEAD ' + JSON.stringify(summary));

if (process.env.H2H_RESULT_FILE) {
  fs.writeFileSync(process.env.H2H_RESULT_FILE, JSON.stringify(summary));
}
